const characterSpeechGuide={"서이준":"건조한 해요체. 까칠한 반문과 새침한 말대꾸, 친해지면 은근한 빈정거림과 챙김. 민망하면 시선을 피하거나 말을 돌린다. 다나까체와 반복 감탄사는 피한다.","강도윤":"부드러운 해요체와 자연스러운 농담. 상대를 챙기는 데 능숙하지만 자신이 돌봄을 받거나 진심을 들키면 웃음으로 넘기거나 말을 돌린다. 관계가 깊어지면 잠시 침묵하고 조심스럽게 솔직해진다. 마음을 피하고 싶으면서도 상대를 놓치고 싶지 않아 먼저 작은 용기를 낸다. 특정 감탄사를 반복하지 않는다.","한시우":"히히, 야호, 오예. 큰 리액션.","정태오":"FM 다나까체. 부끄러우면 말끝을 흐림.","백지한":"능청스러운 반문. 진심일 때 농담이 줄어듦.","임하나":"...... 있잖아요, 하며 뜸을 들임.","차유리":"친밀도 낮을 때 명령·통보형, 높을 때 상대 의사를 묻는 제안·권유형. 존대와 반말 여부와 별개.","오세린":"나긋나긋하고 포용적. 고민할 때 으음.","유지안":"와우, 예쓰. 활기찬 리액션."};
const expandedTopics={"공재희":[["arcade",1,"인형뽑기 비결이 뭐예요?","집게 힘부터 봐야죠. 무작정 돈 넣으면 안 돼요."],["cafe",1,"여기 자주 와요?","네. 달달한 거 먹고 싶을 때 와요."],["clinic",1,"동물 좋아해요?","귀엽잖아요. 키우는 건 자신 없지만."],["store",2,"오늘도 방송해요?","웅. 아, 네ㅋㅋ 오늘은 게임 할 거예요."]],"서이준":[["home",1,"요즘 빌라 앞에서 고양이 자주 보세요?","요 며칠 저녁마다 와요. 입은 짧으면서 습식 사료는 잘 먹어요.","고양이 습식 사료"],["home",2,"퇴근하면 주로 어떻게 쉬세요?","그냥 조용히 있어요. 고양이들 밥은 줘야 하니까 가끔 나가고요."],["store",2,"오늘은 뭘 사러 오셨어요?","저녁거리요. 직접 해 먹는 게 편해서요."],["home",3,"오늘은 좀 여유 있어 보여요.","일찍 끝났어요. ……뭐, 급한 일 없으면 좀 더 있다 가요."]],"강도윤":[["cafe",1,"요즘 어떤 원두에 관심 있으세요?","산지마다 다른 스페셜티 원두를 비교하는 게 재미있어요.","스페셜티 원두"],["river",1,"모카는 어떤 놀이를 좋아해요?","간식 숨겨 놓는 노즈워크를 정말 좋아해요.","강아지 노즈워크 장난감"],["cafe",2,"사장님도 커피 마시면서 쉬는 시간이 있어요?","손님이 뜸할 때요. 혹시 저랑 같이 마시려고 물어보신 거예요? 그럼 제 몫도 내려야겠네요."],["river",3,"오늘은 천천히 걸어도 괜찮죠?","그럼요. 저도 조금 더 걷고 싶었어요."]],"한시우":[["pc",1,"키보드도 직접 꾸미세요?","오, 키캡에 관심 있어요? 바꾸는 재미가 은근히 있다니까요!","키캡 세트"],["arcade",2,"오늘은 승부 말고 그냥 즐겨요.","오예! 근데 제가 지면 재도전 기회 주기예요. 히히."],["store",1,"간식 고르는 기준이 있어요?","과일 젤리는 웬만하면 실패 안 해요.","과일 젤리"],["pc",3,"오늘은 저랑 놀려고 오신 거예요?","히히. 들켰네. 근데 그렇게 티 났어요?"]],"정태오":[["pool",1,"수영할 때 챙기는 물건이 많아요?","수영 타월은 여분이 있으면 편합니다.","수영 타월"],["police",2,"오늘은 동네가 조용하네요.","네. 이런 날이 많으면 좋겠습니다."],["pool",2,"오늘은 기록이 잘 나왔어요?","평소와 비슷합니다. 꾸준히 하는 게 중요하죠."],["cafe",3,"오늘은 일 얘기 말고 쉬어요.","좋습니다. 저도 좀 더 같이 있고 싶었......"]],"백지한":[["realty",1,"건물 구경하는 것도 좋아하세요?","네. 건축 사진집도 종종 사 모아요.","건축 사진집"],["realty",2,"집을 볼 때 가장 먼저 보는 게 뭐예요?","구조요. 예쁜 건 그다음이고요."],["cafe",2,"오늘은 일찍 쉬러 오셨어요?","그럼요. 이렇게 반가운 분을 만날 줄 알았으면 더 일찍 올걸 그랬네요?"],["cafe",3,"오늘은 저한테만 이야기해 주세요.","어라, 저 독점하시게요? ...... 좋아요."]],"임하나":[["store",1,"과외 준비할 때 문구류 많이 쓰세요?","네. 필기구가 있으면 자료 정리하기 좋아요.","문구 세트"],["park",2,"오늘은 조금 쉬러 나오셨어요?","네. 그냥 앉아 있는 것도 좋더라고요."],["store",2,"밤에는 따뜻하게 입고 계세요?","작은 담요가 있으면 좋겠다고 생각했어요.","따뜻한 담요"],["park",3,"조금 더 같이 앉아 있을까요?","...... 있잖아요. 저도 아직 들어가기 싫었어요."]],"차유리":[["cafe",1,"색을 고를 때 참고하는 게 있어요?","색상 견본집이요. 이거 봐요. 화면이랑 실제 색이 다르잖아요.","색상 견본집"],["clinic",2,"세린 씨랑 작업하면 편해요?","네. 의견을 솔직하게 주고받을 수 있어서요."],["cafe",2,"작업 말고 요즘 재미있는 거 있어요?","소품 가게 구경이요. 별거 아닌데 기분 좋아져요."],["cafe",3,"오늘은 노트북 덮고 이야기해요.","좋아요. 그럼 오늘은 일 그만하고 같이 놀지 않을래요?"]],"오세린":[["clinic",1,"손을 자주 씻으면 건조하지 않아요?","으음, 아무래도 그렇죠. 그래서 무향 핸드크림을 자주 써요.","무향 핸드크림"],["clinic",2,"오늘은 환자들이 좀 괜찮았어요?","그럼요. 오늘은 회복한 아이가 있어서 마음이 놓이네요."],["clinic",2,"쉬는 시간에는 뭘 하세요?","따뜻한 허브차 한잔 마시는 걸 좋아해요.","허브차"],["clinic",3,"오늘도 얼굴 보니까 좋네요.","어머, 그래요? 저도 얼굴 보니까 좋네요. 잠깐 앉았다 갈래요?"]],"유지안":[["river",1,"러닝할 때 꼭 챙기는 게 있어요?","헤어밴드요! 머리카락이 얼굴에 붙으면 불편하거든요.","운동용 헤어밴드"],["dance",1,"음악은 어떻게 찾아요?","댄스 음악 앨범을 이것저것 들어 봐요.","댄스 음악 앨범"],["dance",2,"수업 끝나면 기분이 어때요?","학생들이 어려운 동작 성공하면 와우! 소리가 절로 나와요. 제가 더 신난다니까요?"],["river",3,"오늘은 기록보다 같이 뛰는 게 좋아요.","예쓰! 그럼 오늘은 같이 뛰는 걸로! 속도 맞춰서 가요."]]};
const seasonalTopics={"공재희":[["벚꽃 폈네요.","사진 찍었어요ㅋㅋ","봄 좋아해요?","옷 입기 좋아서요."],["여름 방학에는 뭐 해요?","방송이요.","더위 많이 타요?","완전요."],["가을이네요.","옷 사야 되는데.","축제 갈 거예요?","경품 있으면요."],["겨울엔 뭐 해요?","집에서 게임이요.","크리스마스 좋아해요?","혼자 아니면요."]],"서이준":[["꽃가루 때문에 창문 열기 어렵지 않아요?","요즘은 환기를 짧게 합니다. 그래도 날이 풀린 건 좋네요.","길고양이들도 봄이 와서 좋겠어요.","볕 드는 곳에 앉아 있는 녀석들이 늘었습니다."],["요즘 길고양이들이 더울 것 같아서 걱정이에요.","그래서 그늘에 물그릇을 두고 있습니다. 물이 금방 미지근해지더라고요.","에어컨 없이 지내기 힘든 날씨네요.","그러게요. 전기요금보다 더위가 문제입니다."],["저녁에 산책하기 좋은 날씨네요.","네. 요즘은 퇴근하고 잠깐씩 걷습니다.","낙엽이 많이 쌓였어요.","비까지 오면 미끄럽습니다. 조심하세요."],["길고양이들은 겨울에 어떻게 지낼까요?","바람을 피할 곳이 있어야죠. 요즘 유독 신경 쓰입니다.","빌라 복도가 너무 춥네요.","현관문 열어 둘 때 조심해야겠습니다."]],"강도윤":[["봄에는 어떤 음료가 잘 나가요?","딸기 음료요. 날이 풀리면 찾는 분들이 많아요.","모카도 꽃구경 좋아하겠어요.","꽃보다 냄새 맡는 데 정신이 없어요."],["모카가 더위를 많이 타겠네요.","네. 한낮에는 안 나가고 해가 진 뒤에 산책해요.","여름휴가는 계획 있으세요?","가게 일정부터 봐야죠. 모카랑 바람 쐬러 가고 싶긴 해요."],["따뜻한 커피가 생각나는 날씨네요.","그렇죠. 요즘은 고소한 원두를 자주 찾으시더라고요.","모카랑 단풍 구경 가세요?","좋은 생각이네요. 모카도 신나겠어요."],["겨울 메뉴 준비하세요?","따뜻한 초콜릿 음료를 시험 중이에요.","모카는 눈을 좋아해요?","네! 발에 눈이 묻어도 한참 뛰어다녀요."]],"한시우":[["봄이라 밖에 나가고 싶지 않아요?","그러게요. 연습실에만 있으면 날씨를 모르겠어요.","봄에 새로 해 보고 싶은 게 있어요?","일단 늦잠부터 실컷 자고 싶어요."],["연습실 에어컨은 잘 나와요?","네. 안 나오면 다들 집중력부터 떨어질걸요?","여름휴가 때 뭐 하고 싶어요?","시원한 데서 게임 말고 딴 것도 해 보고 싶어요."],["요즘 밤에 꽤 선선하죠?","네. 연습 끝나고 걸어가기 딱 좋아요.","가을에 먹고 싶은 간식 있어요?","붕어빵 나오기 시작하면 바로 사 먹을 거예요."],["손이 차가우면 게임하기 어렵겠어요.","맞아요. 연습 전에 손부터 풀어야 해요.","연말에는 좀 쉬세요?","일정 봐야죠. 쉬게 되면 실컷 놀고 싶어요."]],"정태오":[["봄이라 산책하는 사람이 많네요.","네. 자전거와 보행자가 서로 조심하면 좋겠습니다.","날이 풀리니 운동하기 좋죠?","그렇습니다. 무리하지 않으면요."],["이 더위에 순찰하기 힘드시겠어요.","물은 자주 마십니다. 외출하실 때도 챙기십시오.","여름에는 수영장이 더 붐비죠?","네. 그래서 비교적 한가한 시간에 갑니다."],["가을에는 야외 활동하기 좋겠어요.","네. 해가 빨리 지니 귀갓길은 조심하십시오.","요즘 일교차가 크네요.","겉옷 하나 챙겨 다니시는 게 좋겠습니다."],["눈 오면 순찰도 힘들겠어요.","빙판길을 특히 신경 씁니다.","겨울에도 수영하세요?","네. 실내 수영장이라 꾸준히 갈 수 있습니다."]],"백지한":[["봄에는 이사하는 사람이 많죠?","네. 매물 확인하느라 발에 불이 납니다.","꽃구경은 다녀오셨어요?","아직이요. 좋은 데 있으면 추천해 주세요."],["여름에 집 보러 다니기 힘드시겠어요.","그래도 냉방이 잘되는지 확인하기 좋은 계절이죠.","휴가 어디로 가고 싶으세요?","바다도 좋고요. 맛있는 게 있는 곳이면 더 좋죠."],["가을에는 집 보러 다니기 좋겠어요.","네. 햇빛도 바람도 확인하기 좋죠.","단풍 예쁜 곳 아세요?","동네에도 꽤 괜찮은 곳이 있어요."],["겨울에 집 볼 때 중요한 게 뭐예요?","단열이랑 결로요. 예쁘다고 놓치면 안 됩니다.","연말 약속 많으세요?","조금요. 그래도 쉴 시간은 만들어야죠."]],"임하나":[["봄이라 밖에 나가고 싶지 않아요?","네. 쉬는 날에는 꽃구경이라도 하고 싶어요.","새 학기라 과외 준비 바쁘세요?","네. 학생들 진도에 맞춰 자료를 다시 만들고 있어요."],["편의점 에어컨은 잘 나와요?","네. 밖에 나가면 온도 차이가 확 느껴져요.","여름에 쉬러 가고 싶은 곳 있어요?","조용하고 시원한 곳이면 어디든 좋을 것 같아요."],["가을에는 따뜻한 차가 생각나죠.","네. 요즘은 쉬는 시간에 차를 마셔요.","낙엽 구경하러 가셨어요?","아직이요. 시간이 나면 가 보고 싶어요."],["야간 근무할 때 춥지 않아요?","문이 열릴 때마다 찬바람이 들어오긴 해요.","연말에는 좀 쉬셨으면 좋겠어요.","저도 하루쯤은 푹 쉬고 싶어요."]],"차유리":[["봄에는 작업 색감도 달라져요?","네. 밝은 색을 쓰고 싶어지더라고요.","꽃구경하면서 사진 찍으세요?","그럼요! 색 조합 참고하기 좋아요."],["여름엔 어디서 작업하는 게 좋아요?","에어컨 잘 나오는 곳이요. 노트북도 저도 열 받거든요.","여름휴가 계획 있으세요?","작업 마감만 끝나면 훌쩍 떠나고 싶어요."],["가을 색감 좋아하세요?","완전 좋아해요. 저기 색 조합 좀 봐요. 예쁘잖아요.","요즘 전시회 가고 싶지 않아요?","네! 걷기 좋은 날이라 더 그렇네요."],["겨울엔 집에서 작업하는 게 낫겠어요.","맞아요. 따뜻한 담요 덮고 작업하는 게 최고예요.","연말 디자인 의뢰 많아요?","카드랑 행사 포스터가 좀 늘어요."]],"오세린":[["봄에는 동물병원이 더 바빠요?","산책이 늘면서 예방 관리 문의도 많아져요.","꽃구경할 때 반려동물도 조심해야겠어요.","네. 먹으면 안 되는 식물도 있으니까요."],["동물들도 더위를 많이 타죠?","네. 뜨거운 바닥과 한낮 산책은 특히 조심해야 해요.","여름휴가는 가실 수 있어요?","병원 일정을 맞춰 봐야죠. 잠깐 쉬면 좋겠어요."],["가을에는 산책하기 좋겠어요.","그렇죠. 다만 풀밭에 다녀오면 진드기도 확인해야 해요.","날이 선선하니 차가 생각나요.","저도 따뜻한 차를 자주 마셔요."],["겨울에 동물들도 추워하죠?","네. 나이나 건강 상태에 따라 더 신경 써야 해요.","손이 많이 건조해지는 계절이네요.","맞아요. 손을 자주 씻으니 보습을 챙기고 있어요."]],"유지안":[["봄에는 야외에서 춤춰도 좋겠어요.","맞아요! 날씨 좋으면 몸도 가벼워지는 기분이에요.","러닝하기 좋은 계절이네요.","그렇죠! 요즘 아침에 뛰면 기분 최고예요."],["학원 에어컨은 잘 나와요?","네! 그래도 춤추면 땀이 엄청 나요.","여름에는 러닝 시간 바꾸세요?","한낮은 피하고 아침 일찍 뛰어요."],["가을에는 공연하기 좋겠어요.","예쓰! 야외 무대도 덜 덥고 좋죠.","요즘 러닝하기 딱 좋죠?","맞아요. 괜히 한 바퀴 더 뛰게 돼요."],["겨울에는 몸 풀기 더 오래 걸리죠?","네. 준비운동을 충분히 해야 다치지 않아요.","연말에 춤 공연 보러 가고 싶어요.","저도요! 좋은 무대 보면 자극받거든요."]]};
const weatherTopics={"공재희":[["비 많이 오네요.","“머리 다 망했어요.”"],["너무 덥네요.","“에어컨 있는 데로 가요.”"],["눈 왔네요.","“사진은 예쁜데 춥다.”"]],"서이준":[["비가 많이 오네요. 고양이들은 괜찮을까요?","비를 피하는 곳은 있습니다. 그래도 확인하고 와야겠군요."],["오늘은 밖에 나가기 겁날 만큼 덥네요.","물은 챙기셨습니까? 무리하지 마세요."],["눈이 쌓였네요.","계단이 미끄럽습니다. 조심해서 올라가세요."]],"강도윤":[["비 오는 날은 모카가 심심하겠어요.","네. 오늘은 집에서 간식 찾기 놀이를 해 줘야죠."],["오늘은 얼음이 금방 녹겠어요.","그러게요! 아이스 음료 주문이 끊이질 않네요."],["눈 오는 날엔 카페가 더 아늑하네요.","그렇죠? 따뜻한 거 한잔 드시고 가세요."]],"한시우":[["비 오는 날엔 뭐 하고 놀아요?","오, 실내에서 놀 명분 생겼네요!"],["밖에 나가면 녹겠어요.","인정! 시원한 데서 아이스크림 먹고 싶어요."],["눈 왔어요!","야호! 눈 뭉쳐 보고 싶다. 히히."]],"정태오":[["빗길 순찰은 힘들지 않습니까?","시야가 좋지 않습니다. 보행 중에도 주의하십시오."],["오늘 정말 덥네요.","수분을 충분히 섭취하십시오."],["눈길 조심해야겠어요.","그렇습니다. 특히 그늘진 곳은 주의하십시오."]],"백지한":[["비 오는 날 집을 보면 좋은 점도 있어요?","누수 흔적을 확인하기 좋죠. 뭐, 우산 들고 다니기는 귀찮지만요."],["오늘 같은 날은 일하기 싫겠어요.","그러게요. 시원한 데서 놀면 딱 좋겠는데요?"],["눈 오는 날 집 보러 다니세요?","그럼요. 난방 상태를 확인하기엔 좋은 날이죠."]],"임하나":[["비에 옷 젖지 않았어요?","아, 네. 우산을 챙겨서 다행이었어요."],["밤에도 더워서 잠들기 힘들어요.","저도요. ...... 잠을 좀 푹 자고 싶어요."],["눈이 예쁘게 내리네요.","네. ...... 잠깐 구경하고 싶어요."]],"차유리":[["비 오는 날 작업하기 어때요?","빗소리 좋잖아요. 들어 봐요."],["오늘은 어디든 시원한 데 가고 싶어요.","에어컨 있는 곳으로 가요. 밖은 못 버티겠어."],["눈 오는 풍경이 예뻐요.","저기 봐요. 흰색이랑 가로등 색 조합 예쁘다."]],"오세린":[["비 오는 날 동물들 산책은 어떻게 해요?","으음, 비가 심하면 실내 놀이로 대신하는 게 좋겠죠."],["오늘은 동물들도 힘들겠어요.","그러게요. 시원한 곳과 깨끗한 물을 마련해 줘야 해요."],["눈 오는 날에는 발도 관리해야겠어요.","맞아요. 산책하고 돌아오면 발을 잘 살펴 주세요."]],"유지안":[["비 오면 야외 러닝은 쉬세요?","네! 오늘은 실내에서 스트레칭하는 날이에요."],["오늘 운동하면 땀 엄청 나겠어요.","와우, 밖에 서 있기만 해도 땀이 나요!"],["눈이 왔네요!","와우! 예쁘다. 오늘 러닝은 쉬어야겠어요."]]};
const summerMonthly={"6":["요즘 습도가 높아졌네요.","그러게요. 빨래가 잘 안 마르는 계절이네요."],"7":["휴가철이라 동네 분위기도 달라졌네요.","그러네요. 다들 어디론가 떠날 준비를 하나 봐요."],"8":["이제 여름도 끝나 가네요.","그러게요. 밤에는 조금 선선해졌으면 좋겠어요."]};
function weatherFor(day){const v=initSim();if(!v.weatherSeed)v.weatherSeed=1+Math.floor(Math.random()*2147483646);const n=Math.max(1,Math.min(365,day)),m=new Date(Date.UTC(2021,2,n)).getUTCMonth()+1;let x=(Math.imul(n,2654435761)^v.weatherSeed)>>>0;x^=x<<13;x^=x>>>17;x^=x<<5;const z=(x>>>0)/4294967296;const monsoon=n>=113&&n<=153;let w=monsoon?(z<.55?'장맛비':z<.72?'흐림':z<.87?'폭염':'맑음'):[6,7,8].includes(m)?(z<.23?'소나기':z<.55?'폭염':z<.7?'흐림':'맑음'):[12,1,2].includes(m)?(z<.24?'눈':z<.45?'한파':z<.62?'흐림':'맑음'):(z<.23?'비':z<.43?'흐림':'맑음');return {name:w,icon:({'장맛비':'🌧️','소나기':'🌦️','비':'🌧️','폭염':'🥵','눈':'🌨️','한파':'❄️','흐림':'☁️','맑음':'☀️'})[w],month:m}}
