function takeFriendTopic(owner,p){
 const topics=friendTalkTopics[p];
 if(!topics[owner.friendTalkIndex]){
  const r=socialRecord(p);
  owner.friendTalkIndex=r.nextFriendTalk||0;
  r.nextFriendTalk=(owner.friendTalkIndex+1)%topics.length;
  save();
 }
 return topics[owner.friendTalkIndex];
}
function hasFriendTopicOpening(ev){
 const base=relationshipVoices[ev.person];
 return !!ev.voiceMoment&&base?.slice(2,4).some(line=>ev.voiceMoment===line||ev.voiceMoment.endsWith(', '+line));
}
function friendStoryLine(topic,p,day){return topic.lines[speechRegisterIndex(p,'npc',day)]}
