{const old=personalStoryData['강도윤'];const more=[{"title":"모카의 산책","min":10,"tier":1,"places":["cafe","park"],"lines":[["이야기","모카가 도윤의 다리에 몸을 기댔다."],["강도윤","얘는 제가 빈손으로 와도 좋아하거든요. 아, 물론 간식 들고 오면 두 배로 좋아하고요."]],"options":[["모카랑 같이 걷고 싶어요.","좋죠! 저도 끼워 주시는 거 맞죠?",3],["모카만 데려갈래요.","와, 저 이렇게 버려지는 건가요?",1],["잠시 말없이 함께 있는다.","오늘은 그냥 이렇게 있어도 좋네요.",0]]},{"title":"커피 한 잔의 차이","min":19,"tier":1,"places":["cafe","park"],"lines":[["이야기","도윤이 두 잔의 커피를 내밀었다."],["강도윤","맞혀 보실래요? 제가 더 좋아하는 쪽. 틀려도 벌칙은 없어요. 아마도?"]],"options":[["향이 더 고소한 쪽이요.","오, 제 취향까지 알아내시면 곤란한데요.",3],["잘 모르겠어요.","그럼 한 모금씩 더 마셔 봐요.",2],["잠시 말없이 함께 있는다.","오늘은 그냥 이렇게 있어도 좋네요.",0]]},{"title":"형 앞에서는","min":28,"tier":2,"places":["cafe","park"],"lines":[["이야기","도윤이 봉사활동에 쓸 물품을 정리했다."],["강도윤","태오 형은 군대에서도 저러셨어요. 제가 웃으면서 대충 넘어가려 하면 딱 걸렸죠."]],"options":[["믿을 만한 선배였나 봐요.","네. 그 형한테는 괜히 잘 보이려고 애쓸 필요가 없었어요.",3],["도윤 씨도 대충 넘기지 마요.","앗, 여기서도 검사받는 건가요?",1],["잠시 말없이 함께 있는다.","오늘은 그냥 이렇게 있어도 좋네요.",0]]},{"title":"빈 점포","min":37,"tier":2,"places":["cafe","park"],"lines":[["이야기","도윤이 작은 상가의 임대 안내문을 살폈다."],["강도윤","저기 창가에 바를 놓으면 좋겠죠? 아, 아직 계약할 돈은 따로 모으는 중이에요."]],"options":[["어떤 가게를 만들고 싶어요?","손님 없어도 제가 앉아 있고 싶은 가게요.",3],["지금 가게도 좋잖아요.","그렇죠. 그래서 서두르진 않으려고요.",1],["잠시 말없이 함께 있는다.","오늘은 그냥 이렇게 있어도 좋네요.",0]]},{"title":"내 몫의 부탁","min":46,"tier":2,"places":["cafe","park"],"lines":[["이야기","도윤이 원두 샘플을 꺼내다 멈췄다."],["강도윤","오늘은 제가 부탁 하나 해도 돼요? 시음 좀 도와줘요. 칭찬만 해 주면 안 되고요."]],"options":[["솔직하게 평가할게요.","좋아요. 상처받으면 모카한테 위로받죠, 뭐.",3],["오늘은 시간이 없어요.","그럼 다음에요. 약속은 안 잡아도 괜찮아요.",0],["잠시 말없이 함께 있는다.","오늘은 그냥 이렇게 있어도 좋네요.",0]]}];personalStoryData['강도윤']=[old[0],old[1],old[2],old[3],...more,old[4]].map((e,i)=>({...e,min:10+i*9,tier:i<2?1:i<6?2:3,places:e.places||['cafe']}));personalStoryData['강도윤'][9].gift='직접 고른 블렌드와 레시피 카드';}
