personalStoryData["차유리"]=[{"title":"색을 고르는 날","intro":"유리가 가방에서 작은 색상표를 꺼냈다. 한참 동안 두 칸을 번갈아 짚어 보더니, 연보라색 칸에 손가락을 얹은 채 내 쪽으로 돌려 주었다.","min":10,"tier":1,"places":["cafe","park"],"lines":[["차유리","이 색 예쁘지 않아요? 인쇄하면 또 다르게 나와서 문제지만."]],"options":[["어떤 색이 제일 좋아요?","오늘은 이거요. 내일은 모르죠!",3],["오늘은 다른 이야기를 해요.","좋아요! 뭐 얘기할까요?",0]]},{"title":"마감과 그림","min":19,"tier":1,"places":["cafe","park"],"lines":[["차유리","디자인 마감 끝내고 나면 정작 제 그림 그릴 힘이 없어요."]],"options":[["그래도 그리고 싶어요?","네. 그게 좀 억울하죠.",3],["오늘은 다른 이야기를 해요.","좋아요! 뭐 얘기할까요?",0]]},{"title":"전공 이야기","min":28,"tier":2,"places":["cafe","park"],"lines":[["차유리","원래 순수미술 했어요. 디자인은 먹고살려고 시작했고요."]],"options":[["둘 다 좋아해요?","좋아하는 부분이 달라요. 하나만 고르긴 싫어요.",3],["오늘은 다른 이야기를 해요.","좋아요! 뭐 얘기할까요?",0]]},{"title":"작은 전시","min":37,"tier":2,"places":["cafe","park"],"lines":[["차유리","개인전 한번 해 보고 싶어요. 벽 하나라도 제 그림으로 채우면 좋겠다."]],"options":[["어떤 그림을 걸고 싶어요?","요즘 그리는 것부터요. 아직 보여 주긴 좀 그래요.",3],["오늘은 다른 이야기를 해요.","좋아요! 뭐 얘기할까요?",0]]},{"title":"가게 구경","min":46,"tier":2,"places":["cafe","park"],"lines":[["차유리","소품 가게 구경하다 보면 제가 고른 물건들로 채워 보고 싶어져요."]],"options":[["어떤 물건을 팔고 싶어요?","일단 예쁜 거요. 근데 계산기를 두드리면 좀 달라지죠.",3],["오늘은 다른 이야기를 해요.","좋아요! 뭐 얘기할까요?",0]]},{"title":"작업실의 오후","min":55,"tier":2,"places":["cafe","park"],"lines":[["차유리","오늘은 그림 그릴 거예요. 같이 있어도 되는데 말은 별로 못 해요."]],"options":[["저도 제 할 일 할게요.","오, 좋다. 그럼 각자 열심히 해요.",3],["오늘은 다른 이야기를 해요.","좋아요! 뭐 얘기할까요?",0]]},{"title":"내 그림의 가격","min":64,"tier":3,"places":["cafe","park"],"lines":[["차유리","제 그림에 가격 붙이는 게 생각보다 어렵네요. 싸게 팔기도 싫고."]],"options":[["작업 시간도 계산해 봐요.","맞아요. 재료비만 생각할 일이 아니죠.",3],["오늘은 다른 이야기를 해요.","좋아요! 뭐 얘기할까요?",0]]},{"title":"첫 진열","min":73,"tier":3,"places":["cafe","park"],"lines":[["차유리","작게 만든 엽서를 몇 장 진열해 봤어요. 아직 실험이에요."]],"options":[["반응이 궁금하네요.","저도요. 안 팔리면 제가 쓰죠, 뭐.",3],["오늘은 다른 이야기를 해요.","좋아요! 뭐 얘기할까요?",0]]},{"title":"내 방식대로","min":82,"tier":3,"places":["cafe","park"],"lines":[["차유리","디자인 일도 계속할 거예요. 그림만 그려야 작가인 건 아니잖아요."]],"options":[["유리 씨가 정하는 거죠.","그쵸! 제가 제 일정 정하는 게 제일 좋아요.",3],["오늘은 다른 이야기를 해요.","좋아요! 뭐 얘기할까요?",0]]},{"title":"작은 원화","min":91,"tier":3,"places":["cafe","park"],"lines":[["차유리","이건 제가 그린 거예요. 복제품 아니고 원화. 마음에 들면 가져요."]],"options":[["소중히 간직할게요.","좋아요. 근데 액자는 취향대로 골라요!",3],["오늘은 다른 이야기를 해요.","좋아요! 뭐 얘기할까요?",0]],"gift":"작은 원화"}];
personalStoryData["임하나"]=[{"title":"식기 전에","min":10,"tier":1,"places":["cafe","park","store"],"lines":[["이야기","하나가 휴대전화의 시간을 확인했다."],["임하나","……있잖아요. 저 먼저 가 봐야 할 것 같아요. 동생 저녁을 차려 줘야 해서요."]],"options":[["동생이 직접 차려 먹을 수도 있지 않아요?","……그렇긴 한데, 제가 하는 게 익숙해서요.",3],["다음에 또 만나요.","네. 다음에는 조금 더 오래 있고 싶어요.",1]]},{"title":"비어 있는 시간표","min":19,"tier":1,"places":["cafe","park","store"],"lines":[["이야기","하나의 시간표에는 수업과 아르바이트가 빼곡했다."],["임하나","친구들이 여행 가자고 했는데 이번에도 못 가게 됐어요."]],"options":[["하나 씨는 어디 가고 싶어요?","……바다요. 밤바다도 보고 싶어요.",3],["방학에는 쉴 수 있어요?","아르바이트 시간을 더 늘려야 할 것 같아요.",1]]},{"title":"내 몫의 돈","min":28,"tier":2,"places":["cafe","park","store"],"lines":[["이야기","하나가 가계부를 덮었다."],["임하나","부모님 빚도 있고 동생 등록금도 있어서요. 제 돈을 쓰는 게 조금 어려워요."]],"options":[["하나 씨 생활비도 중요해요.","……제 몫을 따로 생각해 본 적이 별로 없어요.",3],["가족을 돕고 싶군요.","네. 그런데 가끔은 좀 지쳐요.",1]]},{"title":"늦은 귀가","min":37,"tier":2,"places":["cafe","park","store"],"lines":[["이야기","하나가 저녁 하늘을 올려다보았다."],["임하나","오늘은 조금 늦게 들어가도 될 것 같아요. 동생한테 밥 먹으라고 했거든요."]],"options":[["그럼 산책할까요?","……네! 저 이런 시간에 산책하는 거 좋아해요.",3],["오늘은 일찍 들어가요.","아…… 저는 조금 더 있고 싶었는데.",-1]]},{"title":"작은 사치","min":46,"tier":2,"places":["cafe","park","store"],"lines":[["이야기","하나가 진열대 앞에서 한참 망설였다."],["임하나","이거 제가 갖고 싶어서 사도 되는 거겠죠? 꼭 필요한 건 아닌데."]],"options":[["갖고 싶으면 사도 되죠.","……그럼 오늘은 제 거 살래요.",3],["예산을 확인해 봐요.","네. 이번 달에 따로 남겨 둔 돈이 있어요.",1]]},{"title":"처음 하는 거절","min":55,"tier":2,"places":["cafe","park","store"],"lines":[["이야기","하나가 통화를 끝내고 길게 숨을 내쉬었다."],["임하나","이번 주에는 동생 일을 대신 해 줄 수 없다고 했어요. 목소리가 떨려서 혼났지만……."]],"options":[["하나 씨도 일정이 있으니까요.","네. 이번에는 다시 전화해서 취소하지 않을래요.",3],["가족과 다시 이야기해 봐요.","……오늘은 제가 정한 대로 하고 싶어요.",0]]},{"title":"바다에 가는 계획","min":64,"tier":3,"places":["cafe","park","store"],"lines":[["이야기","하나가 기차 시간표를 펼쳤다."],["임하나","저 여행 가려고요. 당일치기라도. 제 돈으로요."]],"options":[["어디부터 구경할 거예요?","바다부터요! ……그리고 맛있는 것도 먹고요.",3],["같이 갈 사람은 있어요?","아직요. 혼자 가는 것도 생각 중이에요.",1]]},{"title":"내가 원하는 공부","min":73,"tier":3,"places":["cafe","park","store"],"lines":[["이야기","하나가 수업 자료를 정리했다."],["임하나","졸업하고 무슨 일을 하고 싶은지 생각해 보려고요. 집에 얼마 보낼지 말고요."]],"options":[["어떤 일이 궁금해요?","아직 모르겠어요. 그래서 알아보려고요.",3],["돈을 많이 버는 게 좋겠죠.","그것도 중요하지만…… 이번에는 다른 것도 생각하고 싶어요.",0]]},{"title":"내일의 약속","min":82,"tier":3,"places":["cafe","park","store"],"lines":[["이야기","하나가 달력에 휴일을 표시했다."],["임하나","이번 달에는 하루를 아예 제 시간으로 비워 놨어요."]],"options":[["뭐 하고 싶어요?","늦잠도 자고, 영화도 보고…… 다 못 해도 괜찮겠죠?",3],["집안일을 미리 끝내요.","이번에는 집안일도 조금 미뤄 볼래요.",0]]},{"title":"나에게 보내는 엽서","min":91,"tier":3,"places":["cafe","park","store"],"lines":[["이야기","하나가 바다 사진이 담긴 엽서를 내밀었다."],["임하나","여행 갔을 때 샀어요. 제 것도 한 장 있어요. ……다음에도 가고 싶어요."]],"options":[["다음 여행도 기대되네요.","네. 이번에는 제가 먼저 날짜를 정할 거예요.",3],["엽서 고마워요.","……마음에 드셨으면 좋겠어요.",1]],"gift":"바다 사진 엽서"}];
personalStoryData["유지안"]=[{"title":"이어폰 한쪽","min":10,"tier":1,"places":["cafe","park","store"],"lines":[["이야기","지안이 음악에 맞춰 발끝을 움직였다."],["유지안","이 부분 들어 봐요. 여기서 안무 딱 들어가면 진짜 멋있는데!"]],"options":[["안무도 직접 짜요?","가끔요. 몸이 먼저 움직인다니까요.",3],["무슨 곡이에요?","잠깐만요. 제목 보내 드릴게요.",1]]},{"title":"연습실의 거울","min":19,"tier":1,"places":["cafe","park","store"],"lines":[["이야기","지안이 예전 연습 영상을 보여 주었다."],["유지안","저 연습생이었거든요. 이때는 거울만 하루 종일 봤어요."]],"options":[["무대가 좋았어요?","완전요. 연습은 죽겠는데 무대는 또 좋더라고요.",3],["힘들었겠어요.","그랬죠. 그래도 재밌는 날도 많았어요.",1]]},{"title":"없어진 데뷔 날짜","min":28,"tier":2,"places":["cafe","park","store"],"lines":[["이야기","지안이 영상 재생을 멈췄다."],["유지안","데뷔할 줄 알았는데 결국 무산됐어요. 그날은 진짜 아무 노래도 듣기 싫었어요."]],"options":[["그때 이야기해 줘서 고마워요.","아, 저 지금 울 것 같아요? 아닌데! ……조금은 맞고요.",3],["다시 도전하면 되잖아요.","그게 그렇게 버튼 하나 누르면 되는 일이 아니더라고요.",-1]]},{"title":"객석에서","min":37,"tier":2,"places":["cafe","park","store"],"lines":[["이야기","지안이 공연 포스터를 바라보았다."],["유지안","공연 보러 가면 신나는데 가끔 배도 아파요. 나도 저기 있고 싶어서."]],"options":[["둘 다 느낄 수 있죠.","그쵸? 응원하다가 질투하고, 또 응원하고. 바쁘다 바빠.",3],["이제 잊는 게 낫지 않아요?","음, 그건 제가 정하고 싶어요.",-2]]},{"title":"몸이 기억하는 것","min":46,"tier":2,"places":["cafe","park","store"],"lines":[["이야기","지안이 음악에 맞춰 짧은 동작을 보여 주었다."],["유지안","와, 아직 되네! 저 방금 좀 멋있지 않았어요?"]],"options":[["한 번 더 보여 줘요.","관람료 받습니다! 농담이고요, 잘 봐요.",3],["오랜만에 춤추는 거예요?","제대로 추는 건 오랜만이죠.",1]]},{"title":"작은 무대","min":55,"tier":2,"places":["cafe","park","store"],"lines":[["이야기","지안이 동네 공연 모집 안내를 펼쳤다."],["유지안","여기 지원해 볼까 봐요. 관객 열 명이어도 무대는 무대잖아요."]],"options":[["어떤 곡 할 거예요?","그게 문제예요. 하고 싶은 게 너무 많아!",3],["큰 무대부터 노려 봐요.","아뇨, 이번엔 제가 즐길 수 있는 것부터요.",0]]},{"title":"틀려도 계속","min":64,"tier":3,"places":["cafe","park","store"],"lines":[["이야기","지안이 연습 영상을 돌려 보며 웃었다."],["유지안","여기 박자 놓쳤죠? 예전 같으면 이거 하나로 하루 종일 우울했을 텐데."]],"options":[["다시 하면 되죠.","맞아요. 근데 이 영상도 남겨 둘래요. 웃기잖아요.",3],["완벽하게 다시 찍어요.","한 번만 더 찍고 끝! 오늘은 쉬어야죠.",1]]},{"title":"공연이 끝난 뒤","min":73,"tier":3,"places":["cafe","park","store"],"lines":[["이야기","지안이 공연을 마친 날의 사진을 보여 주었다."],["유지안","박수 소리 들으니까 진짜 좋더라고요. 규모는 상관없었어요."]],"options":[["다음 무대도 기대돼요.","저도요! 이번에는 끝나고 밥도 제대로 먹었어요.",3],["이제 데뷔 준비 다시 해요?","아직은요. 무대에 서는 방법이 그것만 있는 건 아니니까.",0]]},{"title":"내가 고른 무대","min":82,"tier":3,"places":["cafe","park","store"],"lines":[["이야기","지안이 공연과 연습 일정을 정리했다."],["유지안","춤도 계속 추고 싶고 다른 일도 해 보고 싶어요. 하나만 골라야 하는 건 아니죠?"]],"options":[["지안 씨가 원하는 방식이면 돼요.","좋았어! 그럼 일단 이번 주 연습부터.",3],["한 가지에 집중하는 게 낫지 않아요?","그럴 때도 있겠죠. 지금은 좀 더 해 볼래요.",0]]},{"title":"첫 번째 관객","min":91,"tier":3,"places":["cafe","park","store"],"lines":[["이야기","지안이 작은 공연 사진을 내밀었다."],["유지안","이거 제 첫 동네 공연 사진이에요. 아이돌 데뷔 사진은 아니지만 제 무대니까요."]],"options":[["멋진 무대였겠네요.","다음에는 직접 보러 와요. 진짜 잘할 테니까!",3],["사진 잘 간직할게요.","좋아요! 나중에 유명해지면 귀해질지도?",1]],"gift":"첫 동네 공연 사진"}];
const flirtIntro={"서이준":["…오늘은 좀 더 이야기하고 가면 안 돼요? 딱히 할 일이 있는 건 아니고.","그럼 조금 더 있어요.","…네. 그럼 됐어요."],"강도윤":["오늘은 손님 말고 제가 보고 싶어서 온 거라고 생각해도 될까요?","그렇게 생각해도 돼요.","이런, 오늘 커피는 제가 사야겠네요."],"한시우":["잠깐, 벌써 가요? 와, 오늘 시간 진짜 사기네.","조금 더 놀까요?","오케이! 연장전 간다."],"백지한":["오늘따라 가까이 앉고 싶은데. 옆자리 비었어요?","옆에 앉아요.","좋네요. 다음에도 이 자리 예약할게요."],"임하나":["……저, 다음에는 제가 먼저 만나자고 해도 돼요?","기다리고 있을게요.","네! ……꼭 연락할게요."],"차유리":["오늘 같이 있으니까 재밌네. 다음에도 시간 맞으면 봐요.","나도 또 보고 싶어요.","오, 그럼 좋은 데 찾아 둘게요."],"오세린":["후후. 오늘은 헤어지기가 조금 아쉽네요.","저도 그래요.","그럼 조금만 더 걸을까요?"],"정태오":["시간이 괜찮으시다면 조금 더 함께 있고 싶습니다.","좋아요. 더 있어요.","감사합니다. 오늘은 서두르지 않아도 되겠군요."],"유지안":["어라, 오늘 왜 이렇게 빨리 끝나지? 다음 약속 지금 잡으면 안 돼요?","또 만나고 싶어요.","좋았어! 벌써 기대되는데요?"],"공재희":["아 뭐야 벌써 가요? 나 오늘 좀 재밌었는데ㅋㅋ","나도 더 같이 있고 싶어요.","헐 진짜? 그럼 좀만 더 놀자!"]};
function flirtRecord(p){const v=initSim();v.flirt=v.flirt||{};return v.flirt[p]||(v.flirt[p]={interest:0,dates:0,seen:{},touches:[],history:[]})}
function flirtStage(p){const f=flirtRecord(p);return f.interest>=12?3:f.interest>=6?2:f.interest>0?1:0}
const flirtDaily={"서이준":["편의점에서 이준이 음료 두 개를 꺼냈다.","이거 좋아하셨죠? …아니, 그냥 기억나서요.","내 취향 기억했어요?","기억력이 나쁜 편은 아니라서요. …좋아하면 더 잘 기억하고."],"강도윤":["도윤이 커피잔을 내려놓으며 웃었다.","오늘은 문 열릴 때마다 괜히 쳐다봤네요.","나 기다렸어요?","네. 이제 숨겨 봤자 소용없겠죠?"],"한시우":["시우가 휴대전화 화면을 내밀었다.","이거 보자마자 생각났는데. 와, 나 요즘 뭐만 보면 생각나네?","내 생각 많이 하나 봐요?","아, 들켰다. 이거 감점인가요?"],"백지한":["지한이 당신 옆으로 한 걸음 다가왔다.","오늘 좀 예쁘신데. 그냥 지나가면 제가 손해 보는 기분이라.","오늘만요?","이야, 이걸 받아치시네. 매일요."],"임하나":["하나가 가방에서 작은 간식을 꺼냈다.","제 것 사면서 하나 더 샀어요. ……사실 드리고 싶어서요.","나 생각하면서 골랐어요?","네. 좋아하실 것 같아서 한참 골랐어요."],"차유리":["유리가 휴대전화로 찍은 하늘 사진을 보여 주었다.","이거 예쁘죠? 혼자 보기 아까워서 보여 주고 싶었어요.","다음엔 같이 봐요.","좋다. 날씨 좋은 날 연락할게요."],"오세린":["세린이 걸음을 늦춰 당신과 나란히 섰다.","으음, 오늘은 조금 돌아서 가고 싶네요.","같이 걷고 싶어서요?","네. 알아채셨네요."],"정태오":["태오가 당신을 발견하고 걸음을 멈췄다.","오늘 이 시간에 뵐 줄 알았습니다. …기다린 것은 맞습니다.","기다려 줘서 좋아요.","그렇게 말씀해 주시니 저도 좋습니다."],"유지안":["지안이 멀리서 당신을 발견하고 손을 흔들었다.","와! 오늘 운 좋다. 보고 싶었는데 딱 나타났어요.","나도 보고 싶었어요.","잠깐만, 오늘 기분 너무 좋아졌는데?"],"공재희":["재희가 휴대전화를 주머니에 넣었다.","아까 웃긴 거 봤는데 님한테 제일 먼저 보내고 싶었음ㅋㅋ","앞으로도 먼저 보내 줘요.","웅ㅋㅋ 알았어. 스팸이라고 하지 마요!"]};
