function flirtInviteDays(p){
 const v=initSim(),days=[];
 for(let day=v.day+1;day<=Math.min(v.day+14,298);day++)if(dateBookingSlots(p,day).length)days.push(day);
 return days;
}
function renderFlirtInvite(ev){
 const v=initSim(),p=ev.person,f=flirtRecord(p),a=flirtInvite[p];
 $('progress').textContent='먼저 온 약속 · '+p;
 add(p,a[1]);
 if(ev.answered){add(state.name,ev.selected,true);add(p,ev.response);choiceButton('일정 계속하기',finishEvent);return}
 const finish=(label,reply,day,slot)=>{
  if(ev.answered)return;
  if(day){
   if(day<=v.day||day>Math.min(v.day+14,298)||!dateBookingSlots(p,day).includes(slot))return;
   dateBook()[day]={p,slot,disclosed:false,venue:a[0],initiator:'npc'};
   f.interest+=3;socialRecord(p).interest++;
   remember(p,'flirt:invite','NPC가 먼저 '+a[0]+' 약속을 제안함');
   writeJournal(p+'의 외출 제안 수락 · '+calendarDate(day).label+' '+dayLabels[slot]+' '+a[0]);
   const threads=phoneData().threads;
   (threads[p]||(threads[p]=[])).push({day:v.day,booking:true,playerLine:label,npcLine:reply,reply:1});
  }
  ev.answered=true;ev.selected=label;ev.response=reply;
  f.seen.invite=v.day;f.history.push({day:v.day,id:'invite',accepted:!!day,bookingDay:day||null,slot:day?slot:null});
  save();renderChoiceEvent();renderSim();
 };
 const b=document.createElement('button');b.className='secondary';b.textContent='이 시간에 만나기로 한다';
 const pick=bookingPicker($('suggest'),v.day+1,Math.min(v.day+14,298),day=>dateBookingSlots(p,day),available=>{b.disabled=!available});
 b.onclick=()=>finish(calendarDate(pick.day()).label+' '+dayLabels[pick.slot()]+'에 같이 가요.',a[2],pick.day(),pick.slot());
 $('suggest').append(b);
 choiceButton('이번에는 시간이 안 맞아요.',()=>finish('이번에는 시간이 안 맞아요.','알겠어요. 다음에 기회가 있으면 좋겠네요.',null,null));
}

