const jealousRebuff={"서이준":[["이준의 손이 컵에서 떨어졌다. 시선이 차갑게 가라앉았다.","…알아요. 괜한 말을 했네요.",3],["이준이 입을 다물고 한 박자 늦게 고개를 끄덕였다.","그러죠. …제가 좀 쓸데없는 얘기를 했네요.",2]],"강도윤":[["도윤이 웃었지만 눈가에는 웃음기가 없었다.","그렇죠. 제가 너무 욕심을 냈나 봐요. 미안해요.",3],["도윤이 빈 잔을 괜히 정리했다.","하하. 그럴까요? 무슨 이야기 할래요?",2]],"한시우":[["시우의 웃음이 뚝 끊겼다.","아니, 만나지 말라고 한 건 아닌데. …됐어요. 제가 오버했네요.",3],["시우가 뒷목을 문지르며 헛웃음을 흘렸다.","와, 방금 완전 차단당했네. ㅋㅋ …뭐, 딴 얘기 해요.",2]],"백지한":[["지한의 미소가 옅어졌다. 잠시 당신을 바라보다 등을 기댔다.","알죠. 근데 제가 질투하는 것까지 마음대로 안 되더라고요. …조금 민망하네요.",4],["지한이 입술 안쪽을 깨물고 짧게 웃었다.","이렇게 넘어가시겠다? …알겠어요. 오늘은 그만 물을게요.",3]],"임하나":[["하나가 가방 끈을 놓고 시선을 내렸다.","아…… 네. 그런 뜻으로 말한 건 아니었는데. 죄송해요.",4],["하나가 입을 열었다가 다시 다물었다.","……네. 무슨 이야기 할까요?",3]],"차유리":[["유리가 눈썹을 살짝 찌푸렸다.","그건 당연하죠. 그냥 부럽다고 한 건데. 뭐, 알겠어요.",1],["유리가 어깨를 으쓱했다.","오케이. 굳이 더 얘기할 필요는 없죠.",0]],"오세린":[["세린이 잠시 찻잔을 내려다봤다.","네. 제 감정 때문에 부담을 드리고 싶지는 않았어요. 조금 서운하기는 하네요.",2],["세린이 짧게 숨을 내쉬었다.","그럴까요. 저도 마음을 좀 정리해야겠네요.",1]],"정태오":[["태오의 자세가 한층 반듯해졌다.","…맞는 말씀입니다. 제가 선을 넘었군요.",3],["태오가 잠시 침묵하다 고개를 끄덕였다.","알겠습니다. 이 이야기는 여기까지 하죠.",2]],"유지안":[["지안의 웃음이 어색하게 굳었다.","앗, 그런 뜻은 아니었는데… 미안해요. 좀 민망하다.",2],["지안이 입술을 삐죽였다가 웃었다.","아쉽네. 알겠어요! 딴 얘기 뭐 할까요?",1]],"공재희":[["재희의 표정이 굳었다. 휴대전화를 쥔 손에 힘이 들어갔다.","아, 누가 만나지 말랬어요? 그냥 질투 난다고 한 거잖아요. …됐어요.",6],["재희가 시선을 피하고 휴대전화 화면을 켰다.","아… ㅇㅋ. 말하기 싫으면 말아요. …괜히 말했네.",5]]};
function renderJealousMeet(ev){const v=initSim(),p=ev.person,f=flirtRecord(p),a=jealousMeetScenes[p];$('progress').textContent='두 사람의 순간 · 질투';add('이야기',a[0]);add(p,a[1]);if(ev.answered){add(state.name,ev.selected,true);if(ev.jealousNarration)add('이야기',ev.jealousNarration);add(p,ev.response);choiceButton('일정 계속하기',finishEvent);return}const b=jealousRebuff[p],opts=[[a[2],a[3],true,'',0],['누구와 만날지는 제가 정하고 싶어요.',b[0][1],false,b[0][0],b[0][2]],['오늘은 다른 이야기 할까요?',b[1][1],false,b[1][0],b[1][2]]];for(const [label,reply,warm,narration,hurt] of opts)choiceButton(label,()=>{if(ev.answered)return;ev.answered=true;ev.selected=label;ev.response=reply;ev.jealousNarration=narration;if(hurt)feel(p,{hurt});f.seen.jealousMeet=v.day;f.history.push({day:v.day,id:'jealousMeet',accepted:warm});if(warm){f.interest+=2;feel(p,{jealousy:-2,security:2});remember(p,'flirt:jealousMeet',reply)}save();renderChoiceEvent();renderSim()})}
const hurtMeetScenes={"서이준":["이준이 짧게 인사하고 시선을 돌렸다.","…별일 없으시죠.","지난번 말이 계속 생각나네요. 지금은 좀 거리를 두고 싶어요.","…제 말을 기억하고 있었군요. 조금 생각해 볼게요."],"강도윤":["도윤은 웃었지만 사적인 안부는 묻지 않았다.","어서 오세요. 오늘은 뭐 드릴까요?","요즘은 손님 대하듯 지내는 게 편하네요.","고마워요. 당장 예전처럼 웃기는 어렵겠지만요."],"한시우":["시우가 평소와 달리 장난을 걸지 않았다.","아, 안녕하세요.","괜히 농담했다가 또 민망해지기 싫어서요.","…오케이. 조금씩 다시 얘기해 봐요."],"백지한":["지한이 미소 없이 당신을 바라봤다.","오랜만이네요.","좋아하는 마음이 있다고 계속 아무렇지 않을 수는 없잖아요.","좋아요. 다만 이번엔 말뿐이 아니었으면 좋겠어요."],"임하나":["하나가 손끝을 만지작거리며 고개를 숙였다.","아… 안녕하세요.","저도 계속 참는 게 힘들어요. 오늘은 혼자 있고 싶어요.","……고마워요. 조금만 시간을 주세요."],"차유리":["유리가 이어폰을 빼고 짧게 인사했다.","왔어요?","솔직히 지난번 일은 기분 나빴어요. 당분간 거리를 두고 싶어요.","알겠어요. 다음에 편하게 얘기해요."],"오세린":["세린이 차분히 인사했지만 더 다가오지는 않았다.","잘 지내셨어요?","저도 제 마음을 돌볼 시간이 필요해요.","말해 주셔서 고마워요. 천천히 생각해 볼게요."],"정태오":["태오가 일정한 거리를 두고 인사했다.","안녕하십니까.","당분간 사적인 만남은 조금 줄이고 싶습니다.","알겠습니다. 시간을 두고 이야기하지요."],"유지안":["지안이 웃으려다가 입꼬리를 내렸다.","아, 왔네요.","계속 괜찮은 척하는 것도 좀 힘들어요.","고마워요. 오늘은 조금 쉬고 싶어요."],"공재희":["재희가 당신을 보고 휴대전화를 뒤집어 놓았다.","…왜요?","나 진짜 속상했거든요. 아무렇지도 않은 척하기 싫어요. 오늘은 좀 혼자 있게 해 줘요.","…알겠어요. 근데 나 아직 기분 안 풀렸어요."]};
const hurtMeetReplies={"서이준":[["이준이 짧게 고개를 끄덕였다.","…고마워요. 먼저 갈게요."],["이준의 얼굴에서 표정이 사라졌다.","그쪽한테는 벌써 끝난 얘기인가 보네요. 알겠습니다."]],"강도윤":[["도윤이 힘없이 웃었다.","네. 다음에는 좀 더 편하게 뵐 수 있으면 좋겠네요."],["도윤이 잠시 눈을 감았다가 떴다.","하하. 제가 또 혼자 착각했나 봐요. 더 말씀 안 드릴게요."]],"한시우":[["시우가 주머니에 손을 넣었다.","오케이. 저도 좀 머리 식히고 올게요."],["시우가 헛웃음을 터뜨렸다.","와, 진짜 너무하네. 제가 뭐 그렇게 웃겨요? …아, 됐다."]],"백지한":[["지한이 길게 숨을 내쉬었다.","좋아요. 지금 더 붙잡고 있으면 저도 좋은 말 못 할 것 같네요."],["지한의 턱에 힘이 들어갔다. 당신을 바라보던 눈에서 웃음기가 완전히 사라졌다.","제가 이렇게까지 신경 쓰는 게 우스워요? …됐어요. 저도 더는 매달리고 싶지 않네요."]],"임하나":[["하나가 가방을 가슴 앞으로 끌어안았다.","네…… 배려해 주셔서 감사해요."],["하나가 입술을 떨다가 고개를 들었다.","저도 그만하고 싶어요. 그런데 제 마음은 아직 안 괜찮잖아요……!"]],"차유리":[["유리가 이어폰을 다시 꼈다.","좋아요. 나중에 봐요."],["유리가 눈살을 찌푸리며 가방을 챙겼다.","그럼 더 할 말 없네요. 갈게요."]],"오세린":[["세린이 천천히 고개를 끄덕였다.","네. 서로 생각할 시간을 가지면 좋겠어요."],["세린이 당신을 물끄러미 바라봤다.","제 마음을 이야기하는 것조차 불편하시다면, 더 말씀드릴 이유가 없겠네요."]],"정태오":[["태오가 한 걸음 물러섰다.","배려해 주셔서 감사합니다. 먼저 실례하겠습니다."],["태오의 목소리가 한층 낮아졌다.","제게는 아직 해결되지 않은 일입니다. 더 이상의 사적인 대화는 삼가겠습니다."]],"유지안":[["지안이 작게 손을 흔들었다.","응… 다음엔 좀 더 웃으면서 봐요."],["지안의 눈가가 붉어졌다. 웃으려던 입술이 떨렸다.","나도 맨날 이런 얘기 하기 싫어요! 근데 자꾸 속상한 걸 어떡해요."]],"공재희":[["재희가 휴대전화를 챙기고 입술을 삐죽였다.","…웅. 나중에 연락할게요."],["재희가 벌떡 일어났다. 목소리가 높아졌다.","아 진짜! 내가 뭐 그렇게 귀찮아요? 됐어요. 나 갈래요."]]};
function renderHurtMeet(ev){const v=initSim(),p=ev.person,m=memoryFor(p),a=hurtMeetScenes[p];$('progress').textContent='두 사람의 순간 · 마음의 거리';add('이야기',a[0]);add(p,a[1]);if(ev.hurtLevel>=10)add(p,a[2]);
 const previousFight=m.heatedHurtDay&&m.heatedHurtDay===m.lastHurtMeet&&m.heatedHurtDay<v.day?m.heatedHurtDay:0;
 if(renderArgumentAftermath(ev,'hurt',previousFight,!ev.answered,true))return;
 if(ev.answered){add(state.name,ev.selected,true);if(ev.hurtNarration)add('이야기',ev.hurtNarration);add(p,ev.response);choiceButton('일정 계속하기',finishEvent);return}const b=hurtMeetReplies[p];for(const [label,reply,delta,narration] of [['지난번에 마음이 상했겠어요. 이야기할 준비가 되면 듣고 싶어요.',a[3],-3,''],['알겠어요. 오늘은 각자 시간을 보내요.',b[0][1],0,b[0][0]],['아직도 그 이야기예요? 이제 그만해요.',b[1][1],4,b[1][0]]])choiceButton(label,()=>{if(ev.answered)return;ev.answered=true;ev.selected=label;ev.response=reply;ev.hurtNarration=narration;m.lastHurtMeet=v.day;if(delta>0&&ev.hurtLevel>=10)m.heatedHurtDay=v.day;feel(p,{hurt:delta,security:delta<0?2:delta>0?-3:0});if(delta>0&&m.feelings.hurt>=15)flirtRecord(p).interest=Math.max(0,flirtRecord(p).interest-2);save();renderChoiceEvent();renderSim()})}
function pickFlirt(p,place,jobEvent){const v=initSim();if(!p||!flirtIntro[p]||friendshipRecord(p).bond||v.day>=300||!encounterCanTalk(p,place,null,jobEvent)||relationshipTier(p)<2||!socialRecord(p).contact||aftermathRecord(p))return false;const f=flirtRecord(p),m=memoryFor(p);if(m.feelings.hurt>=5&&(!m.lastHurtMeet||v.day-m.lastHurtMeet>=4))return 'hurtMeet';if(m.feelings.hurt>=10)return false;const social=socialRecord(p),last=social.lastSeen;if(social.jealousKnown&&v.day-social.jealousKnown.day<=14&&(!f.seen.jealousMeet||f.seen.jealousMeet<social.jealousKnown.day)&&Math.max(f.interest,social.interest)>=4)return 'jealousMeet';if(Math.random()>=0.35)return false;if(!f.seen.longing&&f.interest>=6&&last&&v.day-last>=5)return 'longing';if(!f.seen.intro)return 'intro';if(!f.seen.daily&&v.day-f.seen.intro>=5)return 'daily';if(!f.seen.gesture&&f.interest>=3&&v.day-f.seen.daily>=5&&f.seen.daily)return 'gesture';if(!f.seen.invite&&f.seen.gesture&&f.interest>=6&&v.day-f.seen.gesture>=5&&flirtInviteDays(p).length)return 'invite';if(!f.seen.almost&&f.seen.invite&&f.interest>=9&&f.dates>=1&&v.day-f.seen.invite>=5)return 'almost';return false}
function renderLonging(ev){const v=initSim(),p=ev.person,f=flirtRecord(p),a=longingScenes[p];$('progress').textContent='두 사람의 순간 · 오랜만의 만남';add('이야기',a[0]);add(p,a[1]);if(ev.answered){add(state.name,ev.selected,true);add(p,ev.response);choiceButton('일정 계속하기',finishEvent);return}for(const [label,reply,warm] of [[a[2],a[3],true],['요즘 조금 바빴어요. 잘 지냈어요.',individualReplies[p][4],false]])choiceButton(label,()=>{if(ev.answered)return;ev.answered=true;ev.selected=label;ev.response=reply;f.seen.longing=v.day;f.history.push({day:v.day,id:'longing',accepted:warm});if(warm){f.interest+=2;remember(p,'flirt:longing',reply)}save();renderChoiceEvent();renderSim()})}
function renderFlirt(ev){if(ev.flirtScene==='hurtMeet'){if(ev.hurtLevel===undefined)ev.hurtLevel=memoryFor(ev.person).feelings.hurt;renderHurtMeet(ev);return}if(ev.flirtScene==='jealousMeet'){renderJealousMeet(ev);return}if(ev.flirtScene==='longing'){renderLonging(ev);return}if(ev.flirtScene==='invite'){renderFlirtInvite(ev);return}const v=initSim(),p=ev.person,f=flirtRecord(p),id=ev.flirtScene==='almost'?'almost':ev.flirtScene==='gesture'?'gesture':ev.flirtScene==='daily'?'daily':'intro',a=id==='almost'?flirtAlmost[p].slice(1):id==='gesture'?flirtGesture[p].slice(1):id==='daily'?flirtDaily[p].slice(1):flirtIntro[p];$('progress').textContent='두 사람의 순간 · '+p;if(id==='almost')add('이야기',flirtAlmost[p][0]);if(id==='daily')add('이야기',flirtDaily[p][0]);if(id==='gesture')add('이야기',flirtGesture[p][0]);add(p,ev.flirtOpening||(ev.flirtOpening=a[0]));if(ev.answered){add(state.name,ev.selected,true);add(p,ev.response);choiceButton('일정 계속하기',finishEvent);return}for(const [label,reply,warm] of [[a[1],a[2],true],['웃으며 가볍게 인사한다',individualReplies[p][{intro:5,daily:6,gesture:7,almost:8}[id]],false]]){const spoken=contextualChoice(p,label,'flirt');choiceButton(spoken,()=>{if(ev.answered)return;ev.answered=true;ev.selected=spoken;ev.response=reply;f.seen[id]=v.day;f.history.push({day:v.day,id,accepted:warm});if(warm){f.interest+=3;socialRecord(p).interest++;if(id==='gesture'&&['백지한','임하나','유지안','공재희'].includes(p))f.touches.push({day:v.day,type:p==='공재희'?'팔짱':'손잡기',scene:id});remember(p,'flirt:'+id,a[2])}save();renderChoiceEvent();renderSim()})}}
const contactPace={"유지안":[12,3],"한시우":[15,3],"공재희":[10,3],"차유리":[15,3],"강도윤":[18,3],"백지한":[18,3],"오세린":[20,4],"임하나":[20,4],"정태오":[20,4],"서이준":[20,4]};
const storyAdditionalPlaces={"서이준":["home"],"강도윤":["river"],"백지한":["realty"],"정태오":["pool"],"유지안":["river","dance"]};
for(const [p,extra] of Object.entries(storyAdditionalPlaces))for(const e of personalStoryData[p])e.places=[...new Set([...(e.places||['cafe']),...extra])];
function contactReady(p){if(!p||!contactPace[p])return false;const v=initSim(),z=socialRecord(p),a=contactPace[p];return !!v.met[p]&&!z.contact&&(v.affection[p]||0)>=a[0]&&(v.talkCount[p]||0)>=a[1]&&(!z.contactAskedDay||v.day-z.contactAskedDay>=7)&&!['cooling','ready'].includes(aftermathRecord(p)?.status)}
function encounterCanTalk(p,place,activity,jobEvent){const v=initSim();if(!p||!v.running||jobEvent)return false;const a=v.running.plan[v.running.slot];return (p==='서이준'&&place==='home'&&v.neighborMeetingDay===v.day)||a==='자유외출'||['수영','러닝','산책','교류','PC방에서 게임하기','아르바이트','카페 실습'].includes(a)||!!partJobs[a]}
function contactCandidates(ev){if(!ev||!initSim().running||ev.contactFollowup||ev.contactResult||ev.coupleIssue||ev.aftermath||ev.conflictStage||ev.npcBreakup||ev.breakup||ev.exTalk||ev.triangle||ev.crossDeferred)return [];if(ev.group&&ev.answered)return ev.group.people.filter(p=>(ev.groupDelta?.[p]||0)>=0&&contactReady(p));if(ev.volunteerEvent?.answer)return (ev.volunteerEvent.guests||[]).map(x=>x[0]).filter(contactReady);return ev.person&&ev.answered&&Number(ev.delta||0)>=0&&contactReady(ev.person)?[ev.person]:[]}
function renderContactFollowup(ev){const v=initSim(),o=ev.contactFollowup,p=o.people[o.index];$('progress').textContent='연락처 교환 · '+p;add('이야기',p+' 쪽에서 먼저 휴대전화를 꺼냈다.');add(p,contactLines[p]);const answer=o.answers[p];if(answer){add(state.name,answer==='yes'?'좋아요. 연락처를 교환해요.':'아직은 조금 더 친해지고 싶어요.',true);add(p,personalSocialVoice[p][answer==='yes'?0:1]);if(answer==='yes')add('시스템',p+' 연락처를 교환했다.');choiceButton('일정 계속하기',()=>{if(o.index<o.people.length-1){o.index++;ev.person=o.people[o.index];save();renderChoiceEvent()}else finishEvent()});return}for(const [label,k] of [['좋아요. 연락처를 교환해요.','yes'],['아직은 조금 더 친해지고 싶어요.','later']])choiceButton(label,()=>{if(o.answers[p])return;o.answers[p]=k;const z=socialRecord(p);z.contactAskedDay=v.day;if(k==='yes'){z.contact=true;remember(p,'contact:'+v.day,'연락처 교환')}writeJournal(p+' · '+label);save();renderChoiceEvent();renderSim()})}
function storyHint(p){const v=initSim(),n=v.storyProgress?.[p]?.step||0,a=personalStoryData[p]||[],e=a[n];if(!e)return '개인 이야기 '+a.length+'/'+a.length+' · 모두 감상함';const places=(e.places||['cafe']).filter(x=>Array.from({length:7},(_,d)=>d).some(d=>[0,1,2,3].some(slot=>npcPlace(p,d,slot)===x)));const names=places.map(x=>locations.find(y=>y.id===x)?.name||x);const ready=(v.affection[p]||0)>=e.min&&relationshipTier(p)>=e.tier;return '개인 이야기 '+n+'/'+a.length+' · '+(ready?'다음 이야기: '+names.join(' / '):'조금 더 친해지면 새로운 이야기를 들을 수 있다.')+(v.storyProgress?.[p]?.day&&v.day-v.storyProgress[p].day<5?' · 다음 이야기까지 조금 기다리기':'')}

function pickPersonalStory(p,place,activity,jobEvent){const v=initSim(),s=personalStoryData[p],record=v.storyProgress?.[p];if(!s||!encounterCanTalk(p,place,activity,jobEvent))return null;const n=record?.step||0;if(crossPastData[p]&&v.ijunSiwooIntro&&v.day-v.ijunSiwooIntro.day>=5&&!v.crossPastSeen?.[p]&&(!v.crossDeferredDays?.[p]||v.day-v.crossDeferredDays[p]>=7)&&v.affection[p]>=25&&relationshipTier(p)>=2&&crossPastData[p].places.includes(place))return {...crossPastData[p],step:-1};const e=s[n];if(!e||(e.crossReveal&&(!v.ijunSiwooIntro||v.day-v.ijunSiwooIntro.day<5||(v.crossDeferredDays?.[p]&&v.day-v.crossDeferredDays[p]<7)))||!(e.places||['cafe']).includes(place)||v.affection[p]<e.min||relationshipTier(p)<e.tier||(record?.day&&v.day-record.day<5))return null;return {...e,step:n}}
function renderPersonalStory(ev){if(ev.personalStory.crossReveal&&!ev.crossAsked){renderCrossQuestion(ev);return}const v=initSim(),p=ev.person,e=ev.personalStory;$('progress').textContent='개인 이야기 · '+e.title;for(const [who,line] of e.lines)add(who,line);if(ev.answered){add(state.name,ev.selected,true);add(p,ev.response);if(ev.delta)add('시스템',p+' 호감도 '+(ev.delta>0?'+':'')+ev.delta);if(ev.storyGift)add('시스템','상징적인 선물 · '+(e.gift||'도윤이 직접 고른 블렌드와 레시피 카드'));choiceButton('일정 계속하기',finishEvent);return}for(const [label,response,delta] of e.options){const spoken=contextualChoice(p,label,'serious');choiceButton(spoken,()=>{if(ev.answered)return;ev.answered=true;ev.selected=spoken;ev.response=response;const before=v.affection[p];v.affection[p]=Math.max(0,Math.min(999,before+delta));ev.delta=v.affection[p]-before;v.talkCount[p]=(v.talkCount[p]||0)+1;v.storyProgress=v.storyProgress||{};const final=!e.crossReveal&&e.step===personalStoryData[p].length-1;if(e.crossReveal){v.crossPastSeen=v.crossPastSeen||{};v.crossPastSeen[p]=true}else v.storyProgress[p]={step:final&&delta<0?e.step:e.step+1,day:v.day};if(e.step>=2)v.personalEvents[p]=true;if(final&&delta>=0){v.finalEvents[p]=true;v.symbolicGifts[p]=e.gift||'직접 고른 블렌드와 레시피 카드';ev.storyGift=true}remember(p,'story:'+e.step,e.title);feel(p,delta<0?{hurt:3}:{security:2,awareness:1});writeJournal(p+' · '+e.title);save();renderChoiceEvent();renderSim()})}}
