// Reserve at most one added address for an ordinary meeting. Keeping the
// original label in event state also preserves choice history and topic rules.
function meetingCall(p,ev,side,line,position='before'){
 if(singleSpeechTarget(ev)!==p)return line;
 const day=ev.day??initSim().day;
 const turn=(day+people.indexOf(p)+(ev.slot??initSim().slot??0))%4;
 if(turn!==(side==='npc'?0:2)||!agreedAddress(p,side,day))return line;
 const mode=speechRegisterIndex(p,side,day)?'반말':'존댓말';
 return spokenCall(p,side,day,formatSpeech(p,line,side,mode,day),position);
}
function openingAnswerLabel(ev,label){
 if(!ev.voiceMoment||ev.options?.at(-1)?.[3]!=='leave'||ev.options[0][0]!==label)return label;
 return meetingCall(ev.person,ev,'player',label,'after');
}
function renderReunion(ev){const v=initSim(),p=ev.person,s=socialRecord(p),voice=personalSocialVoice[p];if(!ev.reunionOpening){ev.reunionOpening=s.reunionPending?.warm===false?voice[3]:reunionLines[p];save()}add(p,meetingCall(p,ev,'npc',ev.reunionOpening),false,false,ev.reunionOpening===voice[3]?'기본':confessionPortraits[p]?.accepted);
 const warm='저도 오늘 만나서 좋아요.';
 const reunionLabel=label=>label===warm?meetingCall(p,ev,'player',label,'after'):label;
 if(ev.reunionAnswer){add(state.name,reunionLabel(ev.reunionAnswer.label),true);add(p,ev.reunionAnswer.reply);return false}const direct=reunionTalk[p];
const casualOpening=ev.reunionOpening===voice[3];
const choices=(casualOpening||p==='공재희'?direct.slice(0,2):[direct[2]]).map(pair=>[...pair,2]);
if(p==='차유리'&&casualOpening&&ev.place==='cafe'&&['아르바이트','카페 실습'].includes(ev.activity))choices.unshift(['오늘은 여기서 일했어요. 방금 끝났어요.','아, 그래서 앞치마! 저 화면만 보고 있느라 이제 봤어요.',2]);
choices.push([warm,voice[4],3],['이번에는 미리 약속을 잡을까요?',voice[5],4],['잘 지내셨죠?',voice[6],1],['오늘은 인사만 하고 갈게요.',voice[7],0]);
for(const [label,reply,delta] of choices)choiceButton(reunionLabel(label),()=>{if(ev.reunionAnswer)return;ev.reunionAnswer={label,reply};delete s.reunionPending;v.affection[p]=Math.min(999,(v.affection[p]||0)+delta);if(delta===4)s.interest++;save();renderChoiceEvent();renderSim()});return true}
const attachmentDialogue={"공재희":["나만 먼저 연락하는 것 같아서 좀 그래요.","저도 재희 씨 연락 기다려요.","……진짜요?"],"서이준":["요즘은 별것도 아닌 걸로 자꾸 연락하게 되네요. …내가 원래 이런 사람이 아닌데.","연락할 이유가 꼭 있어야 하나요?","…그럼 나중에 귀찮다고 하기 없어요."],"강도윤":["제가 먼저 연락해도 괜찮아요? 바쁠 때 방해했나 싶어서요.","저도 도윤 씨 연락을 기다려요.","……그 말, 생각보다 많이 듣고 싶었나 봐요."],"한시우":["저 원래 약속 하나에 이렇게 신경 안 쓰는데요. 이상하네.","저랑 만나는 게 기대돼요?","어, 그렇게 바로 물어보면…… 네. 기대돼요."],"백지한":["제가 다음 약속을 기다리는 쪽이 될 줄은 몰랐는데요.","저도 다음 약속이 기다려져요.","이러면 제가 더 욕심내고 싶어지잖아요."],"정태오":["연락을 드리고 싶었습니다만, 방해가 될까 싶었습니다.","편하게 연락해 주세요.","…감사합니다. 그렇게 하겠습니다."],"임하나":["제가 먼저 연락하면 귀찮으실까 봐 몇 번이나 문자를 지웠어요.","하나 씨 연락은 반가워요.","……정말요? 다음에는 그냥 보내 볼게요."],"차유리":["같이 있는 건 좋은데 서로 혼자만의 시간도 있었으면 좋겠어요.","저도 그런 관계가 좋아요.","좋네요. 그럼 오래 편하게 볼 수 있겠어요."],"오세린":["요즘 함께 보내는 시간이 제 일상에 자연스럽게 들어왔네요.","저도 그런 게 좋아요.","으음, 서로에게 편안한 시간이면 좋겠어요."],"유지안":["다음 약속이 기대되는데, 괜히 너무 기대하면 안 될 것 같기도 해요.","기대해도 괜찮아요.","……좋아요. 이번에는 솔직하게 기대할래요."]},attachmentBoundary={"공재희":"알겠어요. 근데 바쁘면 바쁘다고 말해 줘요.","서이준":"알겠습니다. 서두르지 않겠습니다.","강도윤":"좋아요. 저도 너무 앞서가지 않을게요.","한시우":"오케이. 평소처럼 놀죠!","백지한":"맞아요. 제가 알아서 조절할게요.","정태오":"알겠습니다. 무리하지 마십시오.","임하나":"네. 저도 제 일 하면서 기다려 볼게요.","차유리":"좋죠. 서로 말하면서 맞추면 되니까.","오세린":"네. 각자의 생활도 중요하죠.","유지안":"맞아요. 천천히 즐겨요!"};
const personalSocialVoice={"서이준":["…저장했어요. 별일 없어도 연락해요.","아, 네. 필요한 일이 있으면 옆집에 있으니까.","…친구라. 그 정도면 저도 괜찮아요.","오랜만이네요. 요즘 통 안 보이던데, 별일 없었어요?","…그래요. 다음엔 그렇게 오래 안 보이지 말고요.","좋아요. 이번엔 날짜부터 잡아요. 또 한참 못 볼까 봐.","뭐, 평소랑 똑같죠. 그쪽은요?","…알겠어요. 다음에 마주치면 봐요.","저도요. 생각보다 시간이 빨리 갔네요.","…들어가요. 길 조심하고요.","안녕하세요. 또 뵙네요.","안녕하세요."],"강도윤":["저장했어요! 다음에 커피 마시러 오실 때 알려 주세요.","하하, 제가 너무 빨랐나요? 편하게 오세요.","좋죠. 커피 친구 하나 생겼네요.","요즘 안 보여서 궁금했어요. 커피는 잘 챙겨 마시고 계세요?","하하, 다음에는 오래 못 기다릴 것 같은데요.","좋아요! 이번엔 제가 커피 마실 시간 비워 둘게요.","그럼요. 얼굴 보니 마음이 놓이네요.","그럼 오늘은 푹 쉬어요. 커피는 다음에 마시죠.","하하, 저까지 기분 좋은 하루였어요.","천천히 가세요. 오늘 와 주셔서 고마워요.","어서 오세요. 오늘은 좀 여유 있으세요?","반갑습니다!"],"한시우":["오예, 저장 완료! 다음에 접속하면 톡 줘요.","앗 오케이! 게임 얘기는 여기서 해도 되니까.","오, 친구 추가 성공! 다음에 같이 놀아요.","와, 진짜 오랜만! 그동안 어디 숨어 있었어요?","그럼 다음엔 이렇게 오래 잠수 타기 없기!","콜! 제 경기 일정 피해서 날짜 잡아요.","저야 뭐, 연습하고 게임하고 그랬죠. 그쪽은요?","ㅇㅋ! 다음에 이어서 놀죠.","오늘 완전 꿀잼이었는데요?","앗 벌써? 다음에 봐요!","오, 안녕하세요! 오늘도 봤네요?","안녕하세요!"],"정태오":["저장했습니다. 필요하시면 연락 주십시오.","알겠습니다. 부담 갖지 마십시오.","좋습니다. 편히 인사해 주십시오.","오랜만입니다. 별일 없으셨습니까?","저도 반갑습니다. 다음에도 뵙겠습니다.","좋습니다. 휴대전화로 일정을 조율하시죠.","예. 별일 없었습니다.","알겠습니다. 남은 일정 잘 마치십시오.","덕분에 편한 시간을 보냈습니다.","귀갓길 조심하십시오.","안녕하십니까. 업무 중이십니까?","안녕하십니까."],"백지한":["저장했어요. 업무 말고 연락해도 되는 거죠?","아, 아직 제 번호는 보류군요. 알겠습니다.","친구요? 그럼 일단 그 자리는 제가 예약하죠.","이렇게 오래 안 보이면 제가 이사라도 가셨나 싶잖아요.","이제 얼굴 봤으니 당분간은 기억이 생생하겠네요.","좋죠. 빈 날짜 먼저 알려 줘요. 제가 맞춰 볼 테니.","저야 여전하죠. 그쪽 소식이 더 궁금했는데.","오늘은 제가 타이밍을 못 맞췄네요. 다음 기회를 노려 보죠.","좋은 시간 값을 톡톡히 했네요.","먼저 보내 드릴게요. 다음에 또 붙잡을 수 있게.","이야, 여기서 또 뵙네요.","반갑습니다."],"임하나":["저장했어요. 저… 먼저 연락해도 괜찮죠?","아, 제가 갑자기 여쭤봤죠. 다음에 인사해요.","친구요? 저 그런 말 듣는 거 오랜만이에요. 좋아요.","…오랜만이에요. 혹시 많이 바쁘셨어요?","저도요. 다음에는 제가 먼저 인사할래요.","네! 제가 아르바이트 없는 날을 찾아 볼게요.","저는 늘 하던 일 했어요. 잘 지내셨으면 좋겠어요.","네, 괜찮아요. 다음에 여유 있을 때 봐요.","저도요. 오늘은 시간 가는 줄 몰랐어요.","조심히 가세요. 저도 조금 있다 들어갈게요.","아… 안녕하세요. 또 뵙네요.","아, 안녕하세요."],"차유리":["저장! 재밌는 전시 발견하면 보내 줄게요.","오케이. 연락처 없어도 동네에서 자주 보겠죠.","친구 좋죠! 나중에 작업 얘기도 들어 줘요.","오, 진짜 오래간만이네요. 어디 좋은 데라도 다녀왔어요?","맞아요. 이렇게 우연히 보는 것도 재밌네요.","좋아요. 서로 마감 없는 날로 잡아 봐요.","저는 작업에 파묻혀 있었죠. 요즘 뭐 해요?","오케이, 각자 할 일 하고 또 봐요.","오늘 같이 나와서 머리가 좀 식었어요.","저도 이제 작업하러 가려고요. 또 봐요!","오, 여기서 만나네요!","오, 안녕하세요!"],"오세린":["저장했어요. 다음에 한가할 때 차 한잔해요.","으음, 천천히 알아가는 것도 좋죠.","서로 일상 이야기 나눌 친구가 생겼네요.","아아, 정말 오랜만이에요. 몸은 잘 챙기셨어요?","그러게요. 다시 편하게 이야기할 수 있어 좋네요.","좋아요. 둘 다 바쁘지 않은 날을 골라요.","저는 병원에서 여전했어요. 요즘 잘 지내시죠?","그럼요. 오늘 무리하지 마시고 편히 쉬세요.","저도 한결 여유로운 시간이었어요.","남은 하루 편안하게 보내세요.","아, 반가워요. 오늘도 잘 지내고 계세요?","안녕하세요. 반가워요."],"유지안":["넵, 저장했어요! 다음에 러닝 같이 해요.","오케이! 그럼 다음에 산책로에서 봐요.","와우! 같이 운동할 친구 생겼다.","헐, 진짜 오랜만! 요즘 뭐 하고 지냈어요?","좋죠! 다음엔 얼굴만 보고 헤어지지 말아요.","콜! 학원 스케줄 보고 운동화 신고 나갈게요.","전 계속 춤추고 있었죠! 그쪽도 잘 지냈어요?","앗, 오늘은 일정이 있군요! 다음에 신나게 놀아요.","완전 재밌었어요! 오늘 에너지 충전 완료.","넵! 집에 가서 스트레칭도 잊지 마요!","와, 또 뵙네요! 오늘도 파이팅이에요.","안녕하세요! 반가워요."],"공재희":["저장했어요ㅋㅋ 나중에 웃긴 거 보내도 됨?","웅 알겠어요. 그럼 오락실에서 보면 인사해요.","친구 됐다ㅋㅋ 다음에 인형뽑기 같이 가요.","아 이제야 보네. 요즘 뭐 했어요?","나도 오늘 봐서 좋음… 다음엔 좀 일찍 봐요.","웅! 이번에는 진짜 날짜 정하는 거예요.","나야 뭐 게임하고 방송했죠ㅋㅋ 그쪽은?","웅… 아쉽긴 한데 다음에 놀아요.","나도요ㅋㅋ 집 가서 오늘 생각날 듯.","웅. 가서 푹 쉬어요.","어, 또 봤네요ㅋㅋ","아 안녕하세요ㅋㅋ"]};
const attachmentProfiles={"서이준":{"min":5,"days":24,"hurt":5,"choices":[["연락할 이유가 없어도 편하게 연락해요.","…그럼 사소한 것도 보내 볼게요.",2,1],["바쁜 때는 서로 기다릴 수 있었으면 해요.","그게 좋겠네요. 답장 재촉하는 건 저도 싫어요.",3,0],["먼저 연락하는 건 서로 번갈아 해요.","…제가 너무 눈치만 봤나 보네요. 해 볼게요.",2,1]]},"강도윤":{"min":4,"days":20,"hurt":5,"choices":[["도윤 씨도 제게 기대도 돼요.","……제가 챙김받는 쪽도 되는 거군요.",3,1],["서로 부담될 땐 먼저 말해요.","좋아요. 저도 웃으면서 괜찮다고만 하진 않을게요.",3,0],["저도 먼저 안부를 물을게요.","하하, 그러면 제 휴대전화도 좀 바빠지겠네요.",2,1]]},"한시우":{"min":6,"days":18,"hurt":4,"choices":[["기대되면 기대된다고 말해도 돼요.","오, 그럼 저 다음 약속 기대 중이라고 선언합니다!",3,1],["경기 전에는 연습에 집중해요.","완전 찬성! 경기 끝나면 제일 먼저 연락할게요.",3,0],["약속 없는 날도 각자 잘 놀아요.","오케이! 다음에 만나면 썰 풀기.",2,0]]},"정태오":{"min":7,"days":28,"hurt":4,"choices":[["용건이 없어도 연락해 주세요.","…그럼 안부를 여쭤보는 것부터 해 보겠습니다.",3,1],["근무 중엔 서로 연락을 기다리지 말아요.","동의합니다. 안전하게 근무를 마치고 연락드리겠습니다.",3,0],["제가 먼저 연락하고 싶은 날도 있어요.","그렇습니까. …기다려 보겠습니다.",2,0]]},"백지한":{"min":5,"days":16,"hurt":6,"choices":[["저도 다음 만남이 기대돼요.","이런 말 들으면 하루 종일 기분 좋겠네요.",2,1],["보고 싶은 마음과 제 일정은 별개예요.","…알아요. 욕심난다고 시간을 전부 달라는 건 아니죠.",3,0],["우리 각자 약속도 지키면서 만나요.","좋죠. 빈 시간은 제가 잘 활용해 볼게요.",3,0]]},"임하나":{"min":4,"days":22,"hurt":4,"choices":[["하나 씨가 하고 싶은 말부터 보내 봐요.","……그럼 오늘은 제가 먼저 잘 자라고 할래요.",3,1],["답이 늦어도 귀찮다는 뜻은 아니에요.","네. 괜히 혼자 결론 내리지 않도록 해 볼게요.",3,0],["제 기분보다 하나 씨 기분도 중요해요.","저도… 제가 원하는 걸 한번 말해 볼게요.",3,1]]},"차유리":{"min":6,"days":28,"hurt":3,"choices":[["저도 혼자만의 시간이 필요해요.","오, 잘 통하네요. 그래야 같이 있을 때 더 재밌죠.",3,1],["마감 때는 각자 시간 보내고 끝나면 만나요.","좋다! 작업하느라 연락 끊겨도 오해하지 말기.",3,0],["저는 조금 더 자주 보고 싶은 편이에요.","음, 날짜를 같이 잡아 볼까요? 작업 시간은 지키고 싶어요.",2,0]]},"오세린":{"min":5,"days":30,"hurt":3,"choices":[["각자의 생활에 자연스럽게 스며들면 좋겠어요.","으음, 저도 그런 관계를 바랐나 봐요.",3,1],["혼자 보내는 휴일도 존중해요.","그럼요. 혼자 쉬어야 충전되는 날도 있으니까요.",3,0],["서로 원하는 게 다르면 이야기해요.","네. 다 맞을 필요는 없죠. 숨기지만 않으면 좋겠어요.",3,0]]},"유지안":{"min":5,"days":19,"hurt":4,"choices":[["다음 약속 기대해도 괜찮아요.","와우! 그럼 하고 싶은 거 리스트부터 만들래요!",3,1],["기대와 별개로 우리 일도 잘 챙겨요.","넵! 제 춤도, 그쪽 일도 응원하기.",3,0],["계획이 달라지면 편하게 이야기해요.","좋아요. 괜히 씩씩한 척만 하지 않을게요.",2,0]]},"공재희":{"min":3,"days":14,"hurt":6,"choices":[["저도 재희 씨 연락이 반가워요.","…진짜요? 나 혼자 기다리는 줄 알았음.",2,1],["답장이 늦어도 마음이 식은 건 아니에요.","웅… 나도 혼자 결론 내리지 않게 해 볼게요.",3,0],["연락하는 시간은 서로 조율해요.","그러면 바쁠 때 말해 줘요. 나도 게임하면서 기다려 볼게요.",3,0]]}};
function attachmentReady(p){const v=initSim(),s=socialRecord(p),a=attachmentProfiles[p];return !platonicOnly(p)&&!!a&&s.contact&&relationshipTier(p)>=3&&s.interest>=a.min&&memoryFor(p).feelings.hurt<a.hurt&&(!s.attachmentDay||v.day-s.attachmentDay>=a.days)}
function renderAttachment(ev){const v=initSim(),p=ev.person,s=socialRecord(p),a=attachmentDialogue[p],profile=attachmentProfiles[p];add(p,a[0]);if(ev.attachmentAnswer){add(state.name,ev.attachmentAnswer.label,true);add(p,ev.attachmentAnswer.reply);choiceButton('일정 계속하기',finishEvent);return}for(const [label,reply,delta,interest] of profile.choices)choiceButton(label,()=>{if(ev.attachmentAnswer)return;ev.attachmentAnswer={label,reply};s.attachmentDay=v.day;s.attachmentHistory=s.attachmentHistory||[];s.attachmentHistory.push({day:v.day,choice:label,reply});feel(p,{security:2});v.affection[p]=Math.min(999,v.affection[p]+delta);s.interest+=interest;remember(p,'attachment:'+v.day,label+' / '+reply);save();renderChoiceEvent();renderSim()})}
function conflictStage(p,place,jobEvent){const v=initSim();if(jobEvent||!v.running)return null;const act=v.running.plan[v.running.slot];if(act!=='자유외출'&&!encounterCanTalk(p,place,act,jobEvent)&&!(place==='cafe'&&['카페 실습','아르바이트'].includes(act)))return null;const y=v.conflicts['차유리'];if(p!=='차유리'&&place==='cafe'&&y?.status==='pending'&&v.day>=y.day+1&&!availablePeople('cafe',dayLabels[v.slot]).includes('차유리'))return 'reflect';if(!p)return null;const x=v.conflicts[p];if(x?.status==='pending')return 'awkward';if(x?.status==='ready'&&v.day>x.reflectedDay)return 'repair';if(x?.status==='ready')return 'awkward';if(p==='차유리'&&!x&&relationshipTier(p)>=2&&['cafe','park'].includes(place))return 'start';return null}
function settleYuriArtConflict(growth){
 const v=initSim(),p='차유리',issue=v.conflicts[p];
 v.conflicts[p]={...issue,status:'resolved',resolvedDay:v.day};
 remember(p,'repair:yuri-art-space','서로의 입장을 이야기하고 화해함');
 const gains=Object.fromEntries(Object.entries(growth||{}).filter(([k,n])=>n>0&&Object.hasOwn(v.innerGrowth,k)));
 return growInner('conflict:yuri-art-space',gains)?Object.entries(gains).map(([k,n])=>k+' +'+n).join(' · '):'';
}
function renderConflict(ev){const v=initSim(),p=ev.person,stage=ev.conflictStage;if(stage==='awkward'){ $('progress').textContent='서먹한 만남';add('이야기','차유리와 눈이 마주쳤다.');add(p,'……왔어요?');add('이야기','가볍게 인사를 건넨 유리는 다시 하던 일에 집중했다. 평소처럼 이야기를 이어 가기는 어려웠다.');choiceButton('조용히 자리를 비킨다',finishEvent);return}if(stage==='reflect'){ $('progress').textContent='성찰 · 창가의 빈자리';add('이야기','차유리가 늘 앉아 작업하던 창가 자리가 비어 있다. 좋아하는 일을 하라는 말이 누군가에게는 무책임한 조언처럼 들릴 수도 있겠다는 생각이 들었다.');choiceButton('다음에 만나면 유리 씨의 이야기를 들어 보자.',()=>{const x=v.conflicts['차유리'];if(x.status==='pending'){x.status='ready';x.reflectedDay=v.day;remember('차유리','reflection:yuri-art-space','창가의 빈자리에서 지난 대화를 돌아봄');writeJournal('차유리 · 지난 대화를 돌아보았다');save()}finishEvent()});return}$('progress').textContent='개인 이야기 · '+(stage==='start'?'그렇게 쉬운 일이 아니야':'다시 생각해 봤어');if(stage==='start'){add(p,'수입 소품이나 포스터를 파는 가게를 열어 볼까 생각 중이에요.');add(state.name,'유리 씨 작품으로 채운 공간도 좋을 것 같은데요.',true);add(p,'……그게 쉬웠으면 내가 진즉 그랬겠지.');add(p,'좋아하는 거랑 그걸로 먹고사는 건 다른 문제예요.')}else{add(p,'저번에 내가 좀 날카로웠죠. 나쁜 뜻으로 한 말 아닌 거 알아요.');add(p,'근데 생각해 봤는데 재밌을 것 같아요. 내 그림으로 채운 가게.')}
if(ev.answered){add(state.name,ev.selected,true);add(p,ev.response);if(ev.growthText)add('시스템',ev.growthText);choiceButton('일정 계속하기',finishEvent);return}
const options=stage==='start'?[['제가 너무 쉽게 말했나 봐요.','……오늘은 다른 얘기 해요.',{hurt:3}],['그냥 가능성을 이야기한 거예요.','알아요. 그래도 지금은 그 얘기 그만하고 싶어요.',{hurt:5}],['제 말에 그렇게 화낼 필요는 없잖아요.','……그래요. 나중에 얘기해요.',{hurt:7}]]:[['제가 미처 생각하지 못한 사정이 있었겠죠.','응. 다음에는 내 얘기도 좀 들어 줘요.',{hurt:-8,security:5},{공감능력:3,자기이해:1}],['저도 그때 조금 서운했어요. 그래도 다시 이야기해서 좋아요.','그랬구나. 미안해요. 다음엔 좀 더 잘 말해 볼게요.',{hurt:-7,security:4},{자기주장:3,공감능력:1}],['가게 이야기는 천천히 해요.','좋아요. 나도 좀 더 생각해 볼게요.',{hurt:-4,security:2},{신중함:0,포용력:1}]];
for(const [label,reply,emotion,growth] of options)choiceButton(label,()=>{if(ev.answered)return;ev.answered=true;ev.selected=label;ev.response=reply;feel(p,emotion);if(stage==='start'){v.conflicts[p]={status:'pending',day:v.day,id:'yuri-art-space'};cancelConflictOutings(p);remember(p,'conflict:yuri-art-space','작품으로 채운 가게에 관한 갈등')}else{ev.growthText=settleYuriArtConflict(growth)}writeJournal(p+' · '+(stage==='start'?'갈등':'화해'));save();renderChoiceEvent();renderSim()})}
function showEvent(place,description,person,activity,jobEvent){$('next').disabled=false;const v=initSim();v.activeEvent={place,person:person||null,activity:activity||null,jobEvent:jobEvent||null,day:v.day,description,expression:'neutral',answered:false};if(person==='공재희'&&place==='arcade'&&relationshipTier(person)>=2&&!v.jaeheeBear&&v.day>v.jaeheeIntro.day&&!jobEvent){v.activeEvent.jaeheeGift=true;socialRecord(person).lastSeen=v.day;save();renderChoiceEvent();return}if(place==='store'&&v.running&&['자유외출','편의점 알바'].includes(v.running.plan[v.running.slot])&&!jobEvent&&!v.ijunSiwooIntro&&v.day>=7&&v.met['서이준']&&v.met['한시우']&&v.slot===3&&['서이준','한시우'].every(p=>npcPlace(p,(v.day-1)%7,v.slot,v.day)==='store')){v.activeEvent.crossIntro=true;v.activeEvent.person=null;v.activeEvent.description='편의점에 들어서자 음료 진열대 앞에 서 있는 서이준과 한시우가 보인다.';save();renderChoiceEvent();return}if(!jobEvent&&v.running){const cm=findCrushMeeting(place,person);if(cm){v.activeEvent.crushMeeting=cm;v.activeEvent.person=cm.lover;save();renderChoiceEvent();return}}if(!jobEvent&&v.running&&v.running.plan[v.running.slot]==='자유외출'&&['cafe','store','park','river','arcade','pool'].includes(place)){const tri=makeTriangle(v.activeEvent,place,null);if(tri){v.activeEvent.triangle=tri;v.activeEvent.person=tri.lover;v.activeEvent.description='익숙한 두 얼굴이 눈에 들어왔다.';save();renderChoiceEvent();return}if(person&&v.met[person])triangleReport(v.activeEvent,place,person)}if(person&&!jobEvent&&v.romance[person]==='dating'&&coupleIssueRecord(person).active){
 const x=everydayIssue(person);
 if(x)v.activeEvent.everydayArgument={mode:'encounter',issueDay:x.day,exit:x.exit,resumed:x.status==='space'};
 else v.activeEvent.coupleIssue=true;
 socialRecord(person).lastSeen=v.day;save();renderChoiceEvent();return}if(person&&!jobEvent&&aftermathRecord(person)&&aftermathRecord(person).status!=='friend'){v.activeEvent.aftermath=true;socialRecord(person).lastSeen=v.day;save();renderChoiceEvent();return}const conflict=conflictStage(person,place,jobEvent);if(conflict){v.activeEvent.conflictStage=conflict;v.activeEvent.description=conflict==='start'?'차유리가 가게에 관한 이야기를 꺼냈다.':conflict==='reflect'?'카페에 들어섰다.':conflict==='awkward'?'익숙한 얼굴이 보인다.':'차유리가 지난번 이야기를 다시 꺼냈다.';if(person)socialRecord(person).lastSeen=v.day;save();renderChoiceEvent();return}if(!person&&!jobEvent&&v.running&&v.running.plan[v.running.slot]==='자유외출'){const ex=exPlaceCandidate(place,v.day);if(ex){v.activeEvent.exMemory={person:ex};save();renderChoiceEvent();return}}if(person&&unresolvedOutingConflict(person)&&!jobEvent){v.activeEvent.conflictStage='awkward';v.activeEvent.description='유리가 이쪽을 보고 걸음을 늦췄다.';save();renderChoiceEvent();return}
const personal=pickPersonalStory(person,place,activity,jobEvent);if(person&&!jobEvent&&socialRecord(person).reunionPending){v.activeEvent.reunion=true;}if(personal&&!v.activeEvent.reunion){v.activeEvent.personalStory=personal;v.activeEvent.description='';}else if(!v.activeEvent.reunion&&!jobEvent&&v.running){const w=pickWeatherScene(person,place,activity);if(w){v.activeEvent.weatherScene=w;v.activeEvent.description=w.description;v.weatherSeen[w.id]=true;}const g=w?null:pickGroup(place,activity);if(g){v.activeEvent.group=g;v.activeEvent.person=g.people[0];v.activeEvent.description='주민들이 같은 장소에 있다.';v.groupSeen[g.id]=v.day;for(const p of g.people)v.met[p]=true}}if(!v.activeEvent.reunion&&!v.activeEvent.personalStory&&!v.activeEvent.weatherScene&&!v.activeEvent.group ){if(speechOfferReady(person,jobEvent))v.activeEvent.speechOffer=true;else{const flirt=pickFlirt(person,place,jobEvent);if(flirt)v.activeEvent.flirtScene=flirt;}}if(person&&!jobEvent&&!v.activeEvent.speechOffer&&!v.activeEvent.flirtScene&&!v.activeEvent.reunion&&!v.activeEvent.personalStory&&!v.activeEvent.weatherScene&&!v.activeEvent.group&&attachmentReady(person))v.activeEvent.attachment=true;for(const who of (v.activeEvent.group?.people||(person?[person]:[])))socialRecord(who).lastSeen=v.day;renderChoiceEvent();save()}
